//! Safe access to LibRaw. Every `unsafe` block in the workspace lives in this
//! crate; `rsb-libraw` forbids `unsafe_code` and calls LibRaw through
//! `Processor`.

mod error;
mod processor;

pub use error::{Error, ErrorCode};
pub use processor::{ImageFormat, MemImage, OutputBps, OutputColor, Processor};

// Generated by bindgen in build.rs. Its layout checks index arrays inside
// `const _` blocks, so they fail the build rather than panic at run time. Its
// unsafe blocks are generated, so they carry no safety comments.
#[allow(non_upper_case_globals)]
#[allow(non_camel_case_types)]
#[allow(non_snake_case)]
#[allow(dead_code)]
#[allow(clippy::undocumented_unsafe_blocks)]
mod bindings {
    include!(concat!(env!("OUT_DIR"), "/bindings.rs"));
}
